#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>
#include <string.h>

/* ------------------------------------------------------------- helpers */

/* Fill dst[0..n-1] with doubles taken from a list/tuple/sequence row.
 * Returns 0 on success, -1 with exception set on failure. */
static int fill_from_sequence(PyObject *obj, double *dst, npy_intp n)
{
    npy_intp i;

    if (PyList_Check(obj)) {
        if (PyList_GET_SIZE(obj) < n) {
            PyErr_SetString(PyExc_ValueError, "row shorter than expected");
            return -1;
        }
        for (i = 0; i < n; i++) {
            PyObject *item = PyList_GET_ITEM(obj, i);
            if (PyFloat_CheckExact(item)) {
                dst[i] = PyFloat_AS_DOUBLE(item);
            } else {
                double v = PyFloat_AsDouble(item);
                if (v == -1.0 && PyErr_Occurred())
                    return -1;
                dst[i] = v;
            }
        }
        return 0;
    }

    if (PyTuple_Check(obj)) {
        if (PyTuple_GET_SIZE(obj) < n) {
            PyErr_SetString(PyExc_ValueError, "row shorter than expected");
            return -1;
        }
        for (i = 0; i < n; i++) {
            PyObject *item = PyTuple_GET_ITEM(obj, i);
            if (PyFloat_CheckExact(item)) {
                dst[i] = PyFloat_AS_DOUBLE(item);
            } else {
                double v = PyFloat_AsDouble(item);
                if (v == -1.0 && PyErr_Occurred())
                    return -1;
                dst[i] = v;
            }
        }
        return 0;
    }

    if (PyArray_Check(obj)) {
        PyArrayObject *arr = (PyArrayObject *)PyArray_FROMANY(
            obj, NPY_DOUBLE, 1, 1, NPY_ARRAY_C_CONTIGUOUS | NPY_ARRAY_FORCECAST);
        if (arr == NULL)
            return -1;
        if (PyArray_DIM(arr, 0) < n) {
            Py_DECREF(arr);
            PyErr_SetString(PyExc_ValueError, "row shorter than expected");
            return -1;
        }
        memcpy(dst, PyArray_DATA(arr), (size_t)n * sizeof(double));
        Py_DECREF(arr);
        return 0;
    }

    /* Generic sequence fallback. */
    for (i = 0; i < n; i++) {
        PyObject *item = PySequence_GetItem(obj, (Py_ssize_t)i);
        double v;
        if (item == NULL)
            return -1;
        v = PyFloat_AsDouble(item);
        Py_DECREF(item);
        if (v == -1.0 && PyErr_Occurred())
            return -1;
        dst[i] = v;
    }
    return 0;
}

/* Extract a 1-D vector of doubles. Returns malloc'ed buffer (caller frees). */
static double *extract_vector(PyObject *obj, npy_intp *n_out)
{
    double *buf;
    npy_intp n;

    if (PyArray_Check(obj)) {
        PyArrayObject *arr = (PyArrayObject *)PyArray_FROMANY(
            obj, NPY_DOUBLE, 1, 1, NPY_ARRAY_C_CONTIGUOUS | NPY_ARRAY_FORCECAST);
        if (arr == NULL)
            return NULL;
        n = PyArray_DIM(arr, 0);
        buf = (double *)malloc((size_t)(n > 0 ? n : 1) * sizeof(double));
        if (buf == NULL) {
            Py_DECREF(arr);
            PyErr_NoMemory();
            return NULL;
        }
        memcpy(buf, PyArray_DATA(arr), (size_t)n * sizeof(double));
        Py_DECREF(arr);
        *n_out = n;
        return buf;
    }

    {
        Py_ssize_t len = PySequence_Size(obj);
        if (len < 0)
            return NULL;
        n = (npy_intp)len;
        buf = (double *)malloc((size_t)(n > 0 ? n : 1) * sizeof(double));
        if (buf == NULL) {
            PyErr_NoMemory();
            return NULL;
        }
        if (fill_from_sequence(obj, buf, n) != 0) {
            free(buf);
            return NULL;
        }
        *n_out = n;
        return buf;
    }
}

static double dot_kernel(const double *a, const double *b, npy_intp n)
{
    double s0 = 0.0, s1 = 0.0, s2 = 0.0, s3 = 0.0;
    npy_intp i = 0;
    for (; i + 4 <= n; i += 4) {
        s0 += a[i] * b[i];
        s1 += a[i + 1] * b[i + 1];
        s2 += a[i + 2] * b[i + 2];
        s3 += a[i + 3] * b[i + 3];
    }
    for (; i < n; i++)
        s0 += a[i] * b[i];
    return (s0 + s1) + (s2 + s3);
}

/* ------------------------------------------------------------- methods */

static PyObject *portfolio_risk_c(PyObject *self, PyObject *args)
{
    PyObject *weights_obj, *cov_obj;
    PyArrayObject *cov_arr = NULL;
    double *w = NULL, *row = NULL;
    double risk_squared = 0.0;
    npy_intp n = 0, i;

    (void)self;
    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &cov_obj))
        return NULL;

    w = extract_vector(weights_obj, &n);
    if (w == NULL)
        return NULL;

    if (PyArray_Check(cov_obj)) {
        const double *data;
        npy_intp stride;

        cov_arr = (PyArrayObject *)PyArray_FROMANY(
            cov_obj, NPY_DOUBLE, 2, 2, NPY_ARRAY_C_CONTIGUOUS | NPY_ARRAY_FORCECAST);
        if (cov_arr == NULL) {
            free(w);
            return NULL;
        }
        if (PyArray_DIM(cov_arr, 0) < n || PyArray_DIM(cov_arr, 1) < n) {
            Py_DECREF(cov_arr);
            free(w);
            PyErr_SetString(PyExc_ValueError,
                            "covariance matrix smaller than weights");
            return NULL;
        }
        data = (const double *)PyArray_DATA(cov_arr);
        stride = PyArray_DIM(cov_arr, 1);

        Py_BEGIN_ALLOW_THREADS
        for (i = 0; i < n; i++)
            risk_squared += w[i] * dot_kernel(data + i * stride, w, n);
        Py_END_ALLOW_THREADS

        Py_DECREF(cov_arr);
        free(w);
        return PyFloat_FromDouble(sqrt(risk_squared));
    }

    /* Sequence-of-rows path (list of lists) -- no NumPy conversion needed. */
    row = (double *)malloc((size_t)(n > 0 ? n : 1) * sizeof(double));
    if (row == NULL) {
        free(w);
        return PyErr_NoMemory();
    }

    {
        int is_list = PyList_Check(cov_obj);
        Py_ssize_t rows = PySequence_Size(cov_obj);
        if (rows < 0 || rows < (Py_ssize_t)n) {
            free(row);
            free(w);
            if (!PyErr_Occurred())
                PyErr_SetString(PyExc_ValueError,
                                "covariance matrix smaller than weights");
            return NULL;
        }
        for (i = 0; i < n; i++) {
            PyObject *row_obj;
            int borrowed = 0;
            if (is_list) {
                row_obj = PyList_GET_ITEM(cov_obj, (Py_ssize_t)i);
                borrowed = 1;
            } else {
                row_obj = PySequence_GetItem(cov_obj, (Py_ssize_t)i);
            }
            if (row_obj == NULL) {
                free(row);
                free(w);
                return NULL;
            }
            if (fill_from_sequence(row_obj, row, n) != 0) {
                if (!borrowed)
                    Py_DECREF(row_obj);
                free(row);
                free(w);
                return NULL;
            }
            if (!borrowed)
                Py_DECREF(row_obj);
            risk_squared += w[i] * dot_kernel(row, w, n);
        }
    }

    free(row);
    free(w);
    return PyFloat_FromDouble(sqrt(risk_squared));
}

static PyObject *portfolio_return_c(PyObject *self, PyObject *args)
{
    PyObject *weights_obj, *returns_obj;
    double *w = NULL, *r = NULL;
    double total;
    npy_intp n = 0, m = 0;

    (void)self;
    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &returns_obj))
        return NULL;

    w = extract_vector(weights_obj, &n);
    if (w == NULL)
        return NULL;
    r = extract_vector(returns_obj, &m);
    if (r == NULL) {
        free(w);
        return NULL;
    }
    if (m < n) {
        free(w);
        free(r);
        PyErr_SetString(PyExc_ValueError, "returns shorter than weights");
        return NULL;
    }

    Py_BEGIN_ALLOW_THREADS
    total = dot_kernel(w, r, n);
    Py_END_ALLOW_THREADS

    free(w);
    free(r);
    return PyFloat_FromDouble(total);
}

